import{_ as e,o as r,c as n,l as a,t as o,N as s}from"./chunks/framework.CMqbtke2.js";const b=JSON.parse('{"title":"ln | x-cmd man (man1) | make links between files","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | ln - make links between files","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ln | x-cmd man (man1) | make links between files"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | ln - make links between files"}]]},"headers":[],"params":{"isMan":true,"man":"ln","category":"man1","desc":"make links between files"},"relativePath":"man1/ln.md","filePath":"man1/ln.md"}'),i={name:"man1/ln.md"},d={class:"visually-hidden"},l=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ln - make links between files</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ln</strong> [<em>OPTION</em>]... [<em>-T</em>] <em>TARGET LINK_NAME</em> <br> <strong>ln</strong> [<em>OPTION</em>]... <em>TARGET</em> <br> <strong>ln</strong> [<em>OPTION</em>]... <em>TARGET</em>... <em>DIRECTORY</em> <br> <strong>ln</strong> [<em>OPTION</em>]... <em>-t DIRECTORY TARGET</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>In the 1st form, create a link to TARGET with the name LINK_NAME. In the 2nd form, create a link to TARGET in the current directory. In the 3rd and 4th forms, create links to each TARGET in DIRECTORY. Create hard links by default, symbolic links with <strong>--symbolic</strong>. By default, each destination (name of new link) should not already exist. When creating hard links, each TARGET must exist. Symbolic links can hold arbitrary text; if later resolved, a relative link is interpreted in relation to its parent directory.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>--backup</strong>[=<em>CONTROL</em>]</dt><dd>make a backup of each existing destination file</dd><dt><strong>-b</strong></dt><dd>like <strong>--backup</strong> but does not accept an argument</dd><dt><strong>-d</strong>, <strong>-F</strong>, <strong>--directory</strong></dt><dd>allow the superuser to attempt to hard link directories (note: will probably fail due to system restrictions, even for the superuser)</dd><dt><strong>-f</strong>, <strong>--force</strong></dt><dd>remove existing destination files</dd><dt><strong>-i</strong>, <strong>--interactive</strong></dt><dd>prompt whether to remove destinations</dd><dt><strong>-L</strong>, <strong>--logical</strong></dt><dd>dereference TARGETs that are symbolic links</dd><dt><strong>-n</strong>, <strong>--no-dereference</strong></dt><dd>treat LINK_NAME as a normal file if it is a symbolic link to a directory</dd><dt><strong>-P</strong>, <strong>--physical</strong></dt><dd>make hard links directly to symbolic links</dd><dt><strong>-r</strong>, <strong>--relative</strong></dt><dd>with <strong>-s</strong>, create links relative to link location</dd><dt><strong>-s</strong>, <strong>--symbolic</strong></dt><dd>make symbolic links instead of hard links</dd><dt><strong>-S</strong>, <strong>--suffix</strong>=<em>SUFFIX</em></dt><dd>override the usual backup suffix</dd><dt><strong>-t</strong>, <strong>--target-directory</strong>=<em>DIRECTORY</em></dt><dd>specify the DIRECTORY in which to create the links</dd><dt><strong>-T</strong>, <strong>--no-target-directory</strong></dt><dd>treat LINK_NAME as a normal file always</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>print name of each linked file</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>The backup suffix is &#39;~&#39;, unless set with <strong>--suffix</strong> or SIMPLE_BACKUP_SUFFIX. The version control method may be selected via the <strong>--backup</strong> option or through the VERSION_CONTROL environment variable. Here are the values:</p><dl><dt>none, off</dt><dd>never make backups (even if <strong>--backup</strong> is given)</dd><dt>numbered, t</dt><dd>make numbered backups</dd><dt>existing, nil</dt><dd>numbered if numbered backups exist, simple otherwise</dd><dt>simple, never</dt><dd>always make simple backups</dd></dl><p>Using <strong>-s</strong> ignores <strong>-L</strong> and <strong>-P</strong>. Otherwise, the last option specified controls behavior when a TARGET is a symbolic link, defaulting to <strong>-P</strong>.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Mike Parker and David MacKenzie.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>link</strong>(2), <strong>symlink</strong>(2)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/ln%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/ln\\</a>&gt; <br> or available locally via: info &#39;(coreutils) ln invocation&#39;</p>',20);function g(t,m,c,h,p,u){return r(),n("div",null,[a("h1",d,o(t.$params.man),1),l])}const k=e(i,[["render",g]]);export{b as __pageData,k as default};
